/**
 * Sub-issue tree rules that need no data access: the error a refused
 * placement raises and the level arithmetic behind the depth limit.
 *
 * A root issue is level 0; `MAX_SUB_ISSUE_DEPTH` bounds the deepest level any
 * issue may sit at.
 */
import { MAX_SUB_ISSUE_DEPTH } from "@/config/constants";

export type IssueHierarchyReason = "cycle" | "too_deep";

/** Raised when a placement would loop the tree or sink it too deep. */
export class IssueHierarchyError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly issueId: string,
    readonly reason: IssueHierarchyReason,
  ) {
    super(
      reason === "cycle"
        ? `Issue ${issueId} cannot be placed under itself or one of its own sub-issues.`
        : `Issue ${issueId} would sit deeper than ${MAX_SUB_ISSUE_DEPTH} levels of sub-issues.`,
    );
    this.name = "IssueHierarchyError";
  }
}

/**
 * Throws `too_deep` unless a subtree of `height` levels (0 for a lone issue)
 * can hang from a parent at `parentLevel`; `issueId` names the issue refused.
 */
export function assertFitsBelow(
  issueId: string,
  parentLevel: number,
  height: number,
): void {
  if (parentLevel + 1 + height > MAX_SUB_ISSUE_DEPTH) {
    throw new IssueHierarchyError(issueId, "too_deep");
  }
}
EOF
