/**
 * Sub-issue tree rules that need no data access: the error a refused
 * placement raises and the level arithmetic behind the depth limit.
 *
 * A root issue is level 0; `MAX_SUB_ISSUE_DEPTH` bounds the deepest level any
 * issue may sit at.
 */
import { MAX_SUB_ISSUE_DEPTH } from "@/config/constants";

export type IssueHierarchyReason = "cycle" | "too_deep";

/** Raised when a placement would loop the tree or sink it too deep. */
export class IssueHierarchyError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly issueId: string,
    readonly reason: IssueHierarchyReason,
  ) {
    super(
      reason === "cycle"
        ? `Issue ${issueId} cannot be placed under itself or one of its own sub-issues.`
        : `Issue ${issueId} would sit deeper than ${MAX_SUB_ISSUE_DEPTH} levels of sub-issues.`,
    );
    this.name = "IssueHierarchyError";
  }
}

/** An issue's place in the tree, without the rest of the row. */
export interface IssueTreeNode {
  readonly id: string;
  readonly parentId: string | null;
}

/**
 * The level of `issueId` given its own node and its ancestors (in any order).
 * Stops at a missing or repeated node, so damaged data cannot loop it.
 */
export function levelOf(
  lineage: readonly IssueTreeNode[],
  issueId: string,
): number {
  const parentOf = new Map(lineage.map((node) => [node.id, node.parentId]));
  const seen = new Set<string>([issueId]);

  let level = 0;
  let cursor = parentOf.get(issueId) ?? null;
  while (cursor !== null && parentOf.has(cursor) && !seen.has(cursor)) {
    seen.add(cursor);
    level += 1;
    cursor = parentOf.get(cursor) ?? null;
  }
  return level;
}

/**
 * How many levels lie below `rootId` given every node beneath it (0 for an
 * issue without sub-issues).
 */
export function subtreeHeight(
  rootId: string,
  below: readonly IssueTreeNode[],
): number {
  const childrenOf = new Map<string, string[]>();
  for (const node of below) {
    if (node.parentId === null) continue;
    const siblings = childrenOf.get(node.parentId) ?? [];
    siblings.push(node.id);
    childrenOf.set(node.parentId, siblings);
  }

  const seen = new Set<string>([rootId]);
  let frontier = [rootId];
  let height = 0;
  while (frontier.length > 0) {
    const next: string[] = [];
    for (const id of frontier) {
      for (const childId of childrenOf.get(id) ?? []) {
        if (seen.has(childId)) continue;
        seen.add(childId);
        next.push(childId);
      }
    }
    if (next.length > 0) height += 1;
    frontier = next;
  }
  return height;
}

