/**
 * Sub-issues: placing and moving, the cycle and depth rules, listing, the
 * roll-up, the archive cascade and the "all sub-issues closed" notice.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { MAX_SUB_ISSUE_DEPTH } from "@/config/constants";
import { subscribe } from "@/lib/event-bus";
import { IssueHierarchyError } from "@/lib/issue-hierarchy";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as issueService from "@/server/services/issue-service";
import { listNotifications, updatePreference } from "@/server/services/notification-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { IssueId, UserId } from "@/types/common";
import type { Issue, IssueStatus } from "@/types/issue";
import type { Actor } from "@/types/member";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;
let stranger: Tenant;
const detachers: Unsubscribe[] = [];

function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

let counter = 0;

async function create(
  t: Tenant,
  options: {
    parent?: Issue | null;
    status?: IssueStatus;
    assignee?: UserId | null;
    project?: Tenant["project"];
    actor?: Actor;
  } = {},
): Promise<Issue> {
  counter += 1;
  return issueService.createIssue(options.actor ?? t.actors.member, {
    ...issueInput(t.org.id, (options.project ?? t.project).id, {
      title: `Sub-issue subject ${counter}`,
      assigneeId: options.assignee ?? null,
    }),
    status: options.status ?? "todo",
    parentId: options.parent?.id ?? null,
  });
}

function setParent(actor: Actor, t: Tenant, issue: Issue, parent: Issue | null) {
  return issueService.setIssueParent(actor, {
    orgId: t.org.id,
    issueId: issue.id,
    parentId: parent?.id ?? null,
  });
}

function setStatus(actor: Actor, t: Tenant, issue: Issue, status: IssueStatus) {
  return issueService.changeIssueStatus(actor, {
    orgId: t.org.id,
    issueId: issue.id,
    status,
  });
}

async function completionNotices(t: Tenant, recipient: UserId) {
  const page = await listNotifications(t.actors.owner, {
    orgId: t.org.id,
    recipientId: recipient,
    unreadOnly: false,
    kind: ["sub_issues_completed"],
    limit: 100,
    cursor: null,
  });
  return page.items;
}

/** A chain of `length` issues, each one the sub-issue of the one before. */
async function chain(t: Tenant, length: number): Promise<Issue[]> {
  const issues: Issue[] = [];
  for (let at = 0; at < length; at += 1) {
    issues.push(await create(t, { parent: issues[at - 1] ?? null }));
  }
  return issues;
}

async function reload(t: Tenant, issue: Issue): Promise<Issue> {
  const found = await issueRepo.findIssueById(t.org.id, issue.id);
  if (found === null) throw new Error("issue vanished");
  return found;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("subissues");
  stranger = await createTenant("subissuesother");
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  cleanup();
});

describe("creating under a parent", () => {
  it("stores the parent id", async () => {
    const parent = await create(tenant);
    const child = await create(tenant, { parent });
    expect(child.parentId).toBe(parent.id);
  });

  it("refuses a parent from another project, creating and announcing nothing", async () => {
    const otherProject = await (
      await import("@/server/repositories/project-repository")
    ).insertProject({
      orgId: tenant.org.id,
      name: "Elsewhere",
      slug: "elsewhere",
      key: "ELSE",
      description: null,
      visibility: "org",
      leadId: tenant.userIds.owner,
      color: "#6366f1",
      targetDate: null,
    });
    const foreign = await create(tenant, { project: otherProject });
    const before = await issueRepo.countIssues(tenant.org.id, tenant.project.id);
    const created = capture("issue.created");

    await expect(create(tenant, { parent: foreign })).rejects.toBeInstanceOf(NotFoundError);

    expect(created).toHaveLength(0);
    expect(await issueRepo.countIssues(tenant.org.id, tenant.project.id)).toBe(before);
  });

  it("refuses a parent from another workspace", async () => {
    const foreign = await create(stranger);
    await expect(create(tenant, { parent: foreign })).rejects.toBeInstanceOf(NotFoundError);
  });

  it("refuses an archived parent", async () => {
    const parent = await create(tenant);
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, parent.id);
    const created = capture("issue.created");

    await expect(create(tenant, { parent })).rejects.toBeInstanceOf(AlreadyArchivedError);
    expect(created).toHaveLength(0);
  });

  it("refuses a parent that would put the issue too deep", async () => {
    const levels = await chain(tenant, MAX_SUB_ISSUE_DEPTH + 1);
    const deepest = levels[MAX_SUB_ISSUE_DEPTH];
    expect(deepest).toBeDefined();

    const error: unknown = await create(tenant, { parent: deepest ?? null }).catch(
      (caught: unknown) => caught,
    );
    expect(error).toBeInstanceOf(IssueHierarchyError);
    expect((error as IssueHierarchyError).reason).toBe("too_deep");
  });

  it("still enforces issue:create before looking at the parent", async () => {
    const parent = await create(tenant);
    await expect(
      create(tenant, { parent, actor: tenant.actors.viewer }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });
});

describe("setIssueParent", () => {
  it("places an issue under a parent and announces issue.updated", async () => {
    const parent = await create(tenant);
    const issue = await create(tenant);
    const updated = capture("issue.updated");

    const after = await setParent(tenant.actors.member, tenant, issue, parent);

    expect(after.parentId).toBe(parent.id);
    expect((await reload(tenant, issue)).parentId).toBe(parent.id);
    expect(updated).toHaveLength(1);
    expect(updated[0]).toMatchObject({
      issueId: issue.id,
      projectId: issue.projectId,
      changedFields: ["parentId"],
    });
  });

  it("moves an issue to another parent and back to the root", async () => {
    const first = await create(tenant);
    const second = await create(tenant);
    const issue = await create(tenant, { parent: first });

    expect((await setParent(tenant.actors.member, tenant, issue, second)).parentId).toBe(
      second.id,
    );

    const updated = capture("issue.updated");
    const root = await setParent(tenant.actors.member, tenant, issue, null);
    expect(root.parentId).toBeNull();
    expect(updated).toHaveLength(1);
    expect(updated[0]?.changedFields).toEqual(["parentId"]);
  });

  it("returns the issue as stored, labels included", async () => {
    const parent = await create(tenant);
    const issue = await create(tenant);
    const after = await setParent(tenant.actors.member, tenant, issue, parent);
    expect(after).toEqual(await reload(tenant, issue));
  });

  it("announces nothing when the parent does not change", async () => {
    const parent = await create(tenant);
    const child = await create(tenant, { parent });
    const root = await create(tenant);
    const updated = capture("issue.updated");

    await setParent(tenant.actors.member, tenant, child, parent);
    await setParent(tenant.actors.member, tenant, root, null);

    expect(updated).toHaveLength(0);
  });

  it("moves the sub-issues along with the issue", async () => {
    const [top, middle, leaf] = await chain(tenant, 3);
    const target = await create(tenant);
    if (!top || !middle || !leaf) throw new Error("chain");

    await setParent(tenant.actors.member, tenant, top, target);

    expect((await reload(tenant, middle)).parentId).toBe(top.id);
    expect((await reload(tenant, leaf)).parentId).toBe(middle.id);
    expect(await issueService.getIssueRollup(tenant.actors.member, tenant.org.id, target.id)).toEqual({
      total: 3,
      open: 3,
      closed: 0,
    });
  });

  it("refuses an actor from another workspace on every operation", async () => {
    const issue = await create(tenant);
    const outsider = stranger.actors.owner;

    await expect(
      issueService.setIssueParent(outsider, {
        orgId: tenant.org.id,
        issueId: issue.id,
        parentId: null,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      issueService.listSubIssues(outsider, tenant.org.id, issue.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      issueService.getIssueRollup(outsider, tenant.org.id, issue.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("does not find an issue of another workspace", async () => {
    const foreign = await create(stranger);
    const mine = await create(tenant);

    await expect(
      setParent(tenant.actors.owner, tenant, foreign, null),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.listSubIssues(tenant.actors.owner, tenant.org.id, foreign.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.getIssueRollup(tenant.actors.owner, tenant.org.id, foreign.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(setParent(tenant.actors.owner, tenant, mine, foreign)).rejects.toBeInstanceOf(
      NotFoundError,
    );
  });

  it("requires issue:update, with the usual escalation for one's own issue", async () => {
    const parent = await create(tenant);
    const issue = await create(tenant);

    await expect(
      setParent(tenant.actors.viewer, tenant, issue, parent),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    const assignedToViewer = await create(tenant, { assignee: tenant.userIds.viewer });
    const placed = await setParent(tenant.actors.viewer, tenant, assignedToViewer, parent);
    expect(placed.parentId).toBe(parent.id);
  });

  it("refuses to move an archived issue", async () => {
    const parent = await create(tenant);
    const issue = await create(tenant);
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);

    await expect(setParent(tenant.actors.member, tenant, issue, parent)).rejects.toBeInstanceOf(
      AlreadyArchivedError,
    );
  });

  it("refuses a parent that is archived, in another project or in another workspace", async () => {
    const issue = await create(tenant);
    const archived = await create(tenant);
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, archived.id);
    const foreign = await create(stranger);

    await expect(setParent(tenant.actors.member, tenant, issue, archived)).rejects.toBeInstanceOf(
      AlreadyArchivedError,
    );
    await expect(setParent(tenant.actors.member, tenant, issue, foreign)).rejects.toBeInstanceOf(
      NotFoundError,
    );
  });

  it("refuses to place an issue under itself or anything below it", async () => {
    const [top, middle, leaf] = await chain(tenant, 3);
    if (!top || !middle || !leaf) throw new Error("chain");
    const updated = capture("issue.updated");

    for (const target of [top, middle, leaf]) {
      const error: unknown = await setParent(tenant.actors.member, tenant, top, target).catch(
        (caught: unknown) => caught,
      );
      expect(error).toBeInstanceOf(IssueHierarchyError);
      expect((error as IssueHierarchyError).reason).toBe("cycle");
      expect((error as IssueHierarchyError).issueId).toBe(top.id);
    }

    expect(updated).toHaveLength(0);
    expect((await reload(tenant, top)).parentId).toBeNull();
  });

  it("judges a move by where the deepest sub-issue would land", async () => {
    // Levels 0..MAX hold a full chain; a second root with its own child is
    // the thing being moved.
    const full = await chain(tenant, MAX_SUB_ISSUE_DEPTH);
    const lastOfFull = full[full.length - 1];
    const [movedTop, movedChild] = await chain(tenant, 2);
    if (!lastOfFull || !movedTop || !movedChild) throw new Error("chain");

    // `movedTop` alone would fit under the second-to-last link (level MAX), but
    // its child would then sit at MAX + 1.
    const secondToLast = full[full.length - 2];
    if (!secondToLast) throw new Error("chain");
    const updated = capture("issue.updated");

    const error: unknown = await setParent(
      tenant.actors.member,
      tenant,
      movedTop,
      secondToLast,
    ).catch((caught: unknown) => caught);
    expect(error).toBeInstanceOf(IssueHierarchyError);
    expect((error as IssueHierarchyError).reason).toBe("too_deep");
    expect(updated).toHaveLength(0);
    expect((await reload(tenant, movedTop)).parentId).toBeNull();
    expect((await reload(tenant, movedChild)).parentId).toBe(movedTop.id);

    // The childless issue fits exactly at the limit.
    const lone = await create(tenant);
    const placed = await setParent(tenant.actors.member, tenant, lone, secondToLast);
    expect(placed.parentId).toBe(secondToLast.id);

    // ...and one level lower it does not.
    const another = await create(tenant);
    await expect(
      setParent(tenant.actors.member, tenant, another, lastOfFull),
    ).rejects.toMatchObject({ reason: "too_deep" });
  });

  it("lets a deep issue become a root again", async () => {
    const levels = await chain(tenant, MAX_SUB_ISSUE_DEPTH + 1);
    const deepest = levels[MAX_SUB_ISSUE_DEPTH];
    if (!deepest) throw new Error("chain");

    const root = await setParent(tenant.actors.member, tenant, deepest, null);
    expect(root.parentId).toBeNull();
  });
});

describe("listSubIssues", () => {
  it("lists the live direct sub-issues, oldest first then by number", async () => {
    const parent = await create(tenant);
    const first = await create(tenant, { parent });
    const second = await create(tenant, { parent });
    const third = await create(tenant, { parent });
    const archived = await create(tenant, { parent });
    await create(tenant, { parent: first });
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, archived.id);

    const listed = await issueService.listSubIssues(
      tenant.actors.viewer,
      tenant.org.id,
      parent.id,
    );

    expect(listed.map((issue) => issue.id)).toEqual([first.id, second.id, third.id]);
  });

  it("breaks creation-time ties by issue number", async () => {
    const parent = await create(tenant);
    const issues = [];
    for (let at = 0; at < 5; at += 1) issues.push(await create(tenant, { parent }));

    // Same instant for every sub-issue.
    const { getDb } = await import("@/server/db");
    getDb().$client
      .prepare("UPDATE issues SET created_at = '2026-03-01T09:00:00.000Z' WHERE parent_id = ?")
      .run(parent.id);

    const listed = await issueService.listSubIssues(tenant.actors.viewer, tenant.org.id, parent.id);
    const numbers = listed.map((issue) => issue.number);
    expect(numbers).toEqual([...numbers].sort((a, b) => a - b));
