describe("archiving a parent", () => {
  it("archives every live issue below it, each announced exactly once", async () => {
    const [top, middle, leaf] = await chain(tenant, 3);
    if (!top || !middle || !leaf) throw new Error("chain");
    const sibling = await create(tenant, { parent: top });
    const archived = capture("issue.archived");

    const result = await issueService.archiveIssue(tenant.actors.member, tenant.org.id, top.id);

    expect(result.id).toBe(top.id);
    expect(result.archivedAt).not.toBeNull();
    for (const issue of [top, middle, leaf, sibling]) {
      expect((await reload(tenant, issue)).archivedAt, issue.id).not.toBeNull();
    }
    expect(archived.map((event) => event.issueId).sort()).toEqual(
      [top.id, middle.id, leaf.id, sibling.id].sort(),
    );
    expect(archived[0]?.issueId).toBe(top.id);
  });

  it("leaves already-archived issues exactly as they were", async () => {
    const top = await create(tenant);
    const early = await create(tenant, { parent: top });
    const live = await create(tenant, { parent: top });
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, early.id);
    const before = await reload(tenant, early);
    const archived = capture("issue.archived");

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, top.id);

    expect(await reload(tenant, early)).toEqual(before);
    expect(archived.map((event) => event.issueId).sort()).toEqual([top.id, live.id].sort());
  });

  it("never touches the parent when a sub-issue is archived", async () => {
    const parent = await create(tenant);
    const child = await create(tenant, { parent });
    const before = await reload(tenant, parent);

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, child.id);

    expect(await reload(tenant, parent)).toEqual(before);
  });
});

describe("the all-sub-issues-closed notice", () => {
  it("tells the parent's assignee once, when the last open sub-issue is closed", async () => {
    const parent = await create(tenant, { assignee: tenant.userIds.admin });
    const first = await create(tenant, { parent });
    const second = await create(tenant, { parent });

    await setStatus(tenant.actors.member, tenant, first, "done");
    expect(await completionNotices(tenant, tenant.userIds.admin)).toHaveLength(0);

    await setStatus(tenant.actors.member, tenant, second, "canceled");
    const notices = await completionNotices(tenant, tenant.userIds.admin);
    expect(
      notices.filter((notice) => notice.href === `/issues/${parent.id}`),
    ).toHaveLength(1);
    expect(notices[0]).toMatchObject({
      kind: "sub_issues_completed",
      actorId: tenant.userIds.member,
    });
  });

  it("tells again after a reopen and a second close", async () => {
    const parent = await create(tenant, { assignee: tenant.userIds.admin });
    const child = await create(tenant, { parent });
    const href = `/issues/${parent.id}`;
    const forParent = async () =>
      (await completionNotices(tenant, tenant.userIds.admin)).filter((n) => n.href === href);

    await setStatus(tenant.actors.member, tenant, child, "done");
    expect(await forParent()).toHaveLength(1);

    await setStatus(tenant.actors.member, tenant, child, "todo");
    expect(await forParent()).toHaveLength(1);

    await setStatus(tenant.actors.member, tenant, child, "done");
    expect(await forParent()).toHaveLength(2);
  });

  it("only considers closings, and only the direct parent", async () => {
    const grand = await create(tenant, { assignee: tenant.userIds.admin });
    const parent = await create(tenant, { parent: grand, assignee: tenant.userIds.owner });
    const child = await create(tenant, { parent });
    const grandHref = `/issues/${grand.id}`;
    const parentHref = `/issues/${parent.id}`;
    const notices = async (who: UserId) => (await completionNotices(tenant, who)).map((n) => n.href);

    // done -> canceled is not a closing.
    await setStatus(tenant.actors.member, tenant, child, "done");
    expect(await notices(tenant.userIds.owner)).toEqual([parentHref]);
    await setStatus(tenant.actors.member, tenant, child, "canceled");
    expect(await notices(tenant.userIds.owner)).toEqual([parentHref]);

    // Closing the child did not tell the grandparent: it still has an open sub-issue.
    expect(await notices(tenant.userIds.admin)).not.toContain(grandHref);

    await setStatus(tenant.actors.member, tenant, parent, "done");
    expect(await notices(tenant.userIds.admin)).toEqual([grandHref]);
  });

  it("waits for open issues deeper down", async () => {
    const parent = await create(tenant, { assignee: tenant.userIds.admin });
    const child = await create(tenant, { parent });
    const grandchild = await create(tenant, { parent: child });
    const href = `/issues/${parent.id}`;
    const forParent = async () =>
      (await completionNotices(tenant, tenant.userIds.admin)).filter((n) => n.href === href);

    await setStatus(tenant.actors.member, tenant, child, "done");
    expect(await forParent()).toHaveLength(0);

    await setStatus(tenant.actors.member, tenant, grandchild, "done");
    // The grandchild's own parent (child) has no assignee, and the grandparent
    // is not its direct parent.
    expect(await forParent()).toHaveLength(0);
  });

  it("stays silent without an assignee, for an archived parent and for the actor", async () => {
    const unassigned = await create(tenant);
    const unassignedChild = await create(tenant, { parent: unassigned });
    await setStatus(tenant.actors.member, tenant, unassignedChild, "done");

    const mine = await create(tenant, { assignee: tenant.userIds.member });
    const mineChild = await create(tenant, { parent: mine });
    await setStatus(tenant.actors.member, tenant, mineChild, "done");
    expect(await completionNotices(tenant, tenant.userIds.member)).toHaveLength(0);

    const archivedParent = await create(tenant, { assignee: tenant.userIds.admin });
    const archivedChild = await create(tenant, { parent: archivedParent });
    await issueRepo.archiveIssue(tenant.org.id, archivedParent.id);
    await setStatus(tenant.actors.member, tenant, archivedChild, "done");

    const toAdmin = await completionNotices(tenant, tenant.userIds.admin);
    expect(toAdmin.map((n) => n.href)).not.toContain(`/issues/${archivedParent.id}`);
  });

  it("is not sent when a sub-issue merely moves away", async () => {
    const parent = await create(tenant, { assignee: tenant.userIds.admin });
    const child = await create(tenant, { parent });
    const other = await create(tenant);

    await setParent(tenant.actors.member, tenant, child, other);

    const hrefs = (await completionNotices(tenant, tenant.userIds.admin)).map((n) => n.href);
    expect(hrefs).not.toContain(`/issues/${parent.id}`);
  });

  it("follows an archive of the last open sub-issue, but not of a closed one", async () => {
    const parent = await create(tenant, { assignee: tenant.userIds.admin });
    const closed = await create(tenant, { parent, status: "done" });
    const open = await create(tenant, { parent });
    const href = `/issues/${parent.id}`;
    const forParent = async () =>
      (await completionNotices(tenant, tenant.userIds.admin)).filter((n) => n.href === href);

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, closed.id);
    expect(await forParent()).toHaveLength(0);

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, open.id);
    expect(await forParent()).toHaveLength(0);

    // A parent whose only sub-issue is archived while open has nothing left to report.
    const sole = await create(tenant, { assignee: tenant.userIds.admin });
    const soleChild = await create(tenant, { parent: sole });
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, soleChild.id);
    const hrefs = (await completionNotices(tenant, tenant.userIds.admin)).map((n) => n.href);
    expect(hrefs).not.toContain(`/issues/${sole.id}`);

    // With a closed sibling left behind, archiving the last open one does report.
    const withSibling = await create(tenant, { assignee: tenant.userIds.admin });
    await create(tenant, { parent: withSibling, status: "done" });
    const lastOpen = await create(tenant, { parent: withSibling });
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, lastOpen.id);
    const after = (await completionNotices(tenant, tenant.userIds.admin)).map((n) => n.href);
    expect(after).toContain(`/issues/${withSibling.id}`);
  });

  it("respects the recipient's preferences", async () => {
    const parent = await create(tenant, { assignee: tenant.userIds.admin });
    const child = await create(tenant, { parent });
    await updatePreference(tenant.actors.admin, {
      orgId: tenant.org.id,
      userId: tenant.userIds.admin,
      kind: "sub_issues_completed",
      inApp: false,
      email: false,
      digestOnly: false,
    });

    await setStatus(tenant.actors.member, tenant, child, "done");

    const hrefs = (await completionNotices(tenant, tenant.userIds.admin)).map((n) => n.href);
    expect(hrefs).not.toContain(`/issues/${parent.id}`);
  });
});

describe("ids", () => {
  it("are plain strings at the schema boundary", () => {
    const id = "x" as IssueId;
    expect(typeof id).toBe("string");
  });
});

