/** Notification kinds accepted by the preference-update schema. */
import { describe, expect, it } from "vitest";
import {
  notificationKindSchema,
  updateNotificationPreferenceSchema,
} from "@/schemas/notification";
import { ALICE, ORG_A } from "../helpers/factories";

describe("schemas/notification", () => {
  it("accepts a preference update for sub_issues_completed", () => {
    expect(notificationKindSchema.safeParse("sub_issues_completed").success).toBe(true);
    expect(
      updateNotificationPreferenceSchema.parse({
        orgId: ORG_A,
        userId: ALICE,
        kind: "sub_issues_completed",
        inApp: true,
        email: false,
        digestOnly: false,
      }).kind,
    ).toBe("sub_issues_completed");
  });

  it("rejects a kind outside the enum", () => {
    expect(notificationKindSchema.safeParse("sub_issues_exploded").success).toBe(false);
  });
});
