cat > tests/lib/issue-hierarchy.test.ts <<'EOF'
/** Level and height arithmetic behind the sub-issue depth limit. */
import { describe, expect, it } from "vitest";
import { MAX_SUB_ISSUE_DEPTH } from "@/config/constants";
import {
  IssueHierarchyError,
  assertFitsBelow,
  levelOf,
  subtreeHeight,
} from "@/lib/issue-hierarchy";

const node = (id: string, parentId: string | null) => ({ id, parentId });

describe("lib/issue-hierarchy", () => {
  it("allows three levels of sub-issues", () => {
    expect(MAX_SUB_ISSUE_DEPTH).toBe(3);
  });

  it("numbers a root as level 0 and each ancestor as one more", () => {
    const lineage = [node("c", "b"), node("a", null), node("b", "a")];
    expect(levelOf(lineage, "a")).toBe(0);
    expect(levelOf(lineage, "b")).toBe(1);
    expect(levelOf(lineage, "c")).toBe(2);
  });

  it("stops on a looped or dangling lineage instead of spinning", () => {
    expect(levelOf([node("a", "b"), node("b", "a")], "a")).toBe(1);
    expect(levelOf([node("a", "gone")], "a")).toBe(0);
  });

  it("measures how many levels lie below an issue", () => {
    expect(subtreeHeight("a", [])).toBe(0);
    expect(subtreeHeight("a", [node("b", "a"), node("c", "a")])).toBe(1);
    expect(
      subtreeHeight("a", [node("b", "a"), node("c", "b"), node("d", "c"), node("x", "a")]),
    ).toBe(3);
    expect(subtreeHeight("a", [node("b", "a"), node("a", "b")])).toBe(1);
  });

  it("refuses a subtree whose deepest issue would pass the limit", () => {
    expect(() => assertFitsBelow("i", MAX_SUB_ISSUE_DEPTH - 1, 0)).not.toThrow();
    expect(() => assertFitsBelow("i", MAX_SUB_ISSUE_DEPTH - 2, 1)).not.toThrow();

    const error: unknown = (() => {
      try {
        assertFitsBelow("i", MAX_SUB_ISSUE_DEPTH - 1, 1);
      } catch (caught) {
        return caught;
      }
      return null;
    })();
    expect(error).toBeInstanceOf(IssueHierarchyError);
    expect(error).toMatchObject({ issueId: "i", reason: "too_deep", code: "conflict" });
  });
});
EOF
