 * Archives the issue together with every live issue below it; issues that
 * were already archived are left as they were. Each issue archived here gets
 * its own `issue.archived`, the requested one first.
 */
export async function archiveIssue(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<Issue> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:archive", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  const rows = await issueRepo.archiveIssueTree(orgId, issueId);
  const archived = rows.find((row) => row.id === issueId);
  const below = rows
    .filter((row) => row.id !== issueId)
    .sort(
      (a, b) =>
        a.createdAt.localeCompare(b.createdAt) || a.number - b.number,
    );

  for (const row of archived ? [archived, ...below] : below) {
    await emit("issue.archived", {
      ...actorEnvelope(actor),
      issueId: row.id,
      projectId: row.projectId,
    });
  }

  // Someone else archived the issue between the read and the write.
  if (!archived) throw new AlreadyArchivedError("Issue", issueId);

  // Issues archived while open stop being open work for whoever is above them.
  const archivedIds = new Set(rows.map((row) => row.id));
  await announceCompletedParents(
    actor,
    rows
      .filter((row) => isOpenStatus(row.status))
      .map((row) =>
        row.parentId !== null && !archivedIds.has(row.parentId)
          ? row.parentId
          : null,
      ),
  );

  return archived;
}

